<?php require dirname(__DIR__).'/bootstrap.php'; use App\Services\GoogleSheetsService;$q=db()->query("SELECT * FROM registrations WHERE status IN('scheduled','rescheduled') AND sheets_synced_at IS NULL LIMIT 100");foreach($q as $r){try{$r['answers']=json_decode($r['form_response_json'],true);(new GoogleSheetsService)->append($r);db()->prepare('UPDATE registrations SET sheets_synced_at=NOW() WHERE id=?')->execute([$r['id']]);echo $r['uuid']." OK\n";}catch(Throwable $e){echo $r['uuid'].' ERROR '.$e->getMessage()."\n";}}
